11	/// Create an etcd lease with the given TTL, tie its lifetime to the [`Runtime`],
12	/// spawn a keep-alive task, and return the lease id (u64).
13	///
14	/// Note: this function spawns a background task that maintains the lease until the runtime is
15	/// shut down or an unrecoverable error occurs. On an unrecoverable error the runtime is shut
16	/// down, honoring the contract that a lost lease shuts the worker down.
17	pub async fn create_lease(
18	    connector: Arc<Connector>,
19	    ttl: u64,
20	    runtime: Runtime,
21	) -> anyhow::Result<u64> {
22	    let token = runtime.primary_token();
23	    if token.is_cancelled() {
24	        anyhow::bail!("lease creation cancelled");
25	    }
26	
27	    let mut lease_client = connector.get_client().lease_client();
28	    let lease = lease_client.grant(ttl as i64, None).await?;
29	
30	    let id = lease.id() as u64;
31	    if token.is_cancelled() {
32	        if let Err(e) = lease_client.revoke(id as i64).await {
33	            tracing::warn!(
34	                lease_id = id,
35	                error = %e,
36	                "Failed to revoke lease after cancellation during creation"
37	            );
38	        }
39	        anyhow::bail!("lease creation cancelled");
40	    }
41	
42	    let ttl = lease.ttl() as u64;
43	    let child = token.child_token();
44	
45	    tokio::spawn(async move {
46	        match keep_alive(connector, id, ttl, child).await {
47	            Ok(_) => tracing::trace!("keep alive task exited successfully"),
48	            Err(e) => {
49	                tracing::error!(
50	                    error = %e,
51	                    "Unable to maintain lease. Check etcd server status"
52	                );
53	                // Phased shutdown (endpoint drain -> backend teardown), not a
54	                // bare primary-token cancel, so teardown is ordered.
55	                runtime.shutdown();
56	            }
57	        }
58	    });
59	
60	    Ok(id)
61	}
62	
63	/// Task to keep leases alive with reconnection support.
64	///
65	/// If this task returns an error, the cancellation token will be invoked on the runtime.
66	async fn keep_alive(
67	    connector: Arc<Connector>,
68	    lease_id: u64,
69	    ttl: u64,
70	    token: CancellationToken,
71	) -> anyhow::Result<()> {
72	    // Deadline when the lease expires
73	    let mut deadline = Instant::now() + Duration::from_secs(ttl);
74	
75	    let mut reconnect = true;
76	    while reconnect {
77	        // Try to establish or re-establish the keep-alive stream
78	        let (sender, receiver) =
79	            match new_keep_alive_stream(&connector, lease_id, &deadline, &token).await? {
80	                Some(stream) => stream,
81	                None => break, // cancelled
82	            };
83	
84	        // Keep-alive loop with the established stream
85	        reconnect = keep_alive_with_stream(
86	            &connector,
87	            sender,
88	            receiver,
89	            lease_id,
90	            &mut deadline,
91	            &token,
92	        )
93	        .await?;
94	    }
95	    Ok(())
96	}
97	
98	/// Establish a new keep-alive stream with automatic retry and reconnection.
99	///
100	/// Returns:
101	///     `Ok(Some((LeaseKeeper, LeaseKeepAliveStream)))` on success.
102	///     `Ok(None)` if cancelled.
103	///     `Err` for unrecoverable errors such as deadline exceeded.
104	async fn new_keep_alive_stream(
105	    connector: &Arc<Connector>,
106	    lease_id: u64,
107	    deadline: &Instant,
108	    token: &CancellationToken,
109	) -> anyhow::Result<Option<(LeaseKeeper, LeaseKeepAliveStream)>> {
110	    loop {
111	        let mut lease_client = connector.get_client().lease_client();
112	        match lease_client.keep_alive(lease_id as i64).await {
113	            Ok((sender, receiver)) => {
114	                tracing::debug!(lease_id, "Established keep-alive stream");
115	                return Ok(Some((sender, receiver))); // success
116	            }
117	            Err(e) => {
118	                tracing::warn!(lease_id, error = %e, "Failed to establish keep-alive stream");
119	
120	                // Try to reconnect with the deadline, but also check for cancellation
121	                tokio::select! {
122	                    biased;
123	
124	                    reconnect_result = connector.reconnect(*deadline) => {
125	                        match reconnect_result {
126	                            Err(e) => return Err(e), // cannot reconnect
127	                            _ => continue, // retry
128	                        }
129	                    }
130	
131	                    _ = token.cancelled() => {
132	                        tracing::debug!(lease_id, "Cancellation token triggered during reconnection");
133	                        return Ok(None); // cancelled
134	                    }
135	                }
136	            }
137	        };
138	    }
139	}
140	
141	/// Keep-alive loop that maintains the lease using the provided sender and receiver.
142	///
143	/// Returns:
144	///     `Ok(true)` for recoverable errors such as stream closure that warrant reconnection attempts.
145	///     `Ok(false)` if cancelled.
146	///     `Err` for unrecoverable errors such as lease already expired.
147	async fn keep_alive_with_stream(
148	    connector: &Arc<Connector>,
149	    mut sender: LeaseKeeper,
150	    mut receiver: LeaseKeepAliveStream,
151	    lease_id: u64,
152	    deadline: &mut Instant,
153	    token: &CancellationToken,
154	) -> anyhow::Result<bool> {
155	    loop {
156	        let next_renewal = deadline
157	            .saturating_duration_since(Instant::now())
158	            .div_f64(2.0);
159	
160	        tokio::select! {
161	            biased;
162	
163	            status = receiver.message() => {
164	                match status {
165	                    Ok(Some(resp)) => {
166	                        tracing::trace!(lease_id, "keep alive response received: {:?}", resp);
167	                        // Update deadline from response
168	                        let ttl = resp.ttl();
169	                        if ttl <= 0 {
170	                            tracing::error!(lease_id, "Keep-alive lease expired");
171	                            anyhow::bail!("Unable to maintain lease - expired or revoked. Check etcd server status");
172	                        }
173	                        *deadline = Instant::now() + Duration::from_secs(ttl as u64);
174	                    }
175	                    Ok(None) => {
176	                        tracing::warn!(lease_id, "Keep-alive stream unexpectedly ended");
177	                        return Ok(true); // Exit to reconnect
178	                    }
179	                    Err(e) => {
180	                        tracing::warn!(lease_id, error = %e, "Keep-alive stream error");
181	                        return Ok(true); // Exit to reconnect
182	                    }
183	                }
184	            }
185	
186	            _ = token.cancelled() => {
187	                tracing::debug!(lease_id, "cancellation token triggered; revoking lease");
188	                let mut lease_client = connector.get_client().lease_client();
189	                if let Err(e) = lease_client.revoke(lease_id as i64).await {
190	                    tracing::warn!(
191	                        lease_id,
192	                        error = %e,
193	                        "Failed to revoke lease during cancellation. Cleanup may be incomplete."
194	                    );
195	                }
196	                return Ok(false);
197	            }
198	
199	            _ = tokio::time::sleep(next_renewal) => {
200	                tracing::trace!(lease_id, "sending keep alive");
201	                if let Err(e) = sender.keep_alive().await {
202	                    tracing::warn!(
203	                        lease_id,
204	                        error = %e,
205	                        "Unable to send lease heartbeat. Check etcd server status"
206	                    );
207	                }
208	            }
209	        }
210	    }
211	}
