222	        let runtime = Runtime::from_current().unwrap();
223	
224	        // Stands in for a serving endpoint; Phase 1 cancels the endpoint
225	        // shutdown token, cascading to this child.
226	        let endpoint_token = runtime.child_token();
227	        let primary_token = runtime.primary_token();
228	
229	        // Hold a graceful task so Phase 2 cannot advance to Phase 3 yet.
230	        let guard = runtime.graceful_shutdown_tracker().register_task();
231	
232	        runtime.shutdown();
233	
234	        // Phase 1 cancels the endpoint token promptly.
235	        tokio::time::timeout(Duration::from_secs(5), endpoint_token.cancelled())
236	            .await
237	            .expect("Phase 1 must cancel the endpoint token on lease loss");
