239	        // While the graceful task is outstanding, Phase 3 must not have torn
240	        // down the primary token. A bare-cancel regression fails this assert.
241	        assert!(
242	            !primary_token.is_cancelled(),
243	            "primary token must not be cancelled while a graceful task is outstanding"
244	        );
245	
