843	        if let (Ok(username), Ok(password)) = (
844	            std::env::var(env_etcd::auth::ETCD_AUTH_USERNAME),
845	            std::env::var(env_etcd::auth::ETCD_AUTH_PASSWORD),
846	        ) {
