849	        } else if let (Ok(ca), Ok(cert), Ok(key)) = (
850	            std::env::var(env_etcd::auth::ETCD_AUTH_CA),
851	            std::env::var(env_etcd::auth::ETCD_AUTH_CLIENT_CERT),
852	            std::env::var(env_etcd::auth::ETCD_AUTH_CLIENT_KEY),
853	        ) {
