874	    match std::env::var(env_etcd::ETCD_ENDPOINTS) {
875	        Ok(possible_list_of_urls) => possible_list_of_urls
876	            .split(',')
877	            .map(|s| s.to_string())
878	            .collect(),
879	        Err(_) => vec!["http://localhost:2379".to_string()],
880	    }
