3	
4	//! Uses ZMQ PUB/SUB pattern for one-way event broadcasting:
5	//! - Publishers bind to endpoints and broadcast events
6	//! - Subscribers connect to endpoints and receive events
7	//! - Topic-based filtering at socket level for efficiency
8	//!
9	//! ## Message Format
10	//!
11	//! ZMQ multipart message:
12	//! - Frame 0: Topic (string) - for ZMQ subscription filtering
13	//! - Frame 1: publisher_id (8 bytes, u64 big-endian) - for fast deduplication
14	//! - Frame 2: sequence (8 bytes, u64 big-endian) - for fast deduplication
15	//! - Frame 3: Binary frame (5-byte header + EventEnvelope payload)
16	
17	use anyhow::{Result, anyhow};
18	use async_stream::stream;
19	use async_trait::async_trait;
20	use bytes::Bytes;
21	use futures::{SinkExt, StreamExt};
22	use std::sync::{Arc, OnceLock};
23	use thiserror::Error;
24	use tmq::{
25	    AsZmqSocket, Context, Message, Multipart, SocketBuilder,
26	    publish::{Publish, publish},
27	    subscribe::{Subscribe, subscribe},
28	};
29	use tokio::sync::{Mutex, broadcast};
30	use tokio_util::task::AbortOnDropHandle;
31	
32	/// Returns the process-wide shared ZMQ context.
33	///
34	/// libzmq spawns background I/O threads per `Context`, so all PUB/SUB sockets
35	/// share one. `zmq::Context` is reference-counted; clones drive the same context.
36	fn shared_zmq_context() -> Context {
37	    static CONTEXT: OnceLock<Context> = OnceLock::new();
38	    CONTEXT.get_or_init(Context::new).clone()
39	}
40	
41	/// High Water Mark (HWM) for ZMQ sockets.
42	/// This controls the maximum number of messages that can be queued.
43	/// Default ZMQ HWM is 1000, which limits scalability.
44	const ZMQ_SNDHWM: i32 = 100_000; // Send buffer: 100K messages
45	const ZMQ_RCVHWM: i32 = 100_000; // Receive buffer: 100K messages
46	const ZMQ_SNDTIMEOUT_MS: i32 = 0; // Send timeout: fail fast under pressure
47	const ZMQ_RCVTIMEOUT_MS: i32 = 100; // Receive timeout: 100ms (avoids blocking forever)
48	
49	use super::codec::{Codec, MsgpackCodec};
50	use super::frame::Frame;
51	use super::transport::{EventTransportRx, EventTransportTx, WireStream};
52	use crate::discovery::EventTransportKind;
53	
