102	    /// then binds ZMQ to that port.
103	    ///
104	    /// Returns the transport and the actual bound endpoint.
105	    pub async fn bind(endpoint: &str, topic: &str) -> Result<(Self, String)> {
106	        let actual_endpoint = if endpoint.ends_with(":0") {
107	            let listener = tokio::net::TcpListener::bind("0.0.0.0:0").await?;
108	            let actual_addr = listener.local_addr()?;
