114	            endpoint.to_string()
115	        };
116	
117	        let ctx = shared_zmq_context();
118	        let socket = configure_publish_builder(publish(&ctx)).bind(&actual_endpoint)?;
119	
120	        tracing::info!(
121	            endpoint = %actual_endpoint,
122	            topic = %topic,
123	            sndhwm = ZMQ_SNDHWM,
124	            "ZMQ PUB transport bound with configured HWM"
125	        );
126	
127	        Ok((
128	            Self {
129	                socket: Arc::new(Mutex::new(socket)),
130	                topic: topic.to_string(),
131	            },
132	            actual_endpoint,
133	        ))
