189	    async fn publish(&self, _subject: &str, envelope_bytes: Bytes) -> Result<()> {
190	        let codec = MsgpackCodec;
191	        let (publisher_id, sequence) = codec.decode_envelope_identity(&envelope_bytes)?;
192	
193	        let frame = Frame::new(envelope_bytes);
194	        let frames = vec![
195	            self.topic.as_bytes().to_vec(),
196	            publisher_id.to_be_bytes().to_vec(),
197	            sequence.to_be_bytes().to_vec(),
198	            frame.encode().to_vec(),
199	        ];
200	
201	        self.socket
202	            .lock()
203	            .await
204	            .send(Multipart::from(frames))
205	            .await?;
206	
207	        Ok(())
208	    }
209	
210	    fn kind(&self) -> EventTransportKind {
211	        EventTransportKind::Zmq
212	    }
213	}
