271	impl ValidatedZmqSource {
272	    pub async fn connect_default(
273	        endpoint: &str,
274	        topic: &str,
275	        expected_publisher_id: u64,
276	    ) -> Result<Self> {
277	        Self::connect(endpoint, topic, expected_publisher_id, ZMQ_RCVHWM).await
278	    }
279	
280	    pub async fn connect(
281	        endpoint: &str,
282	        topic: &str,
283	        expected_publisher_id: u64,
284	        rcvhwm: i32,
285	    ) -> Result<Self> {
286	        Ok(Self {
287	            stream: ZmqSubTransport::connect_single_consumer_with_rcvhwm(endpoint, topic, rcvhwm)
288	                .await?,
289	            expected_topic: topic.to_string(),
290	            expected_publisher_id,
291	            codec: Codec::default(),
292	        })
293	    }
294	
295	    pub async fn next(
296	        &mut self,
297	    ) -> Option<std::result::Result<ValidatedEnvelope, ValidatedZmqSourceError>> {
298	        let message = match self.stream.next().await? {
299	            Ok(message) => message,
300	            Err(error) => return Some(Err(ValidatedZmqSourceError::Receive(error))),
301	        };
302	        let envelope = match self.codec.decode_envelope(&message.payload) {
303	            Ok(envelope) => envelope,
304	            Err(error) => {
305	                return Some(Err(ValidatedZmqSourceError::EnvelopeDecode(error)));
306	            }
307	        };
308	
309	        if envelope.publisher_id != self.expected_publisher_id
310	            || envelope.publisher_id != message.publisher_id
311	            || envelope.sequence != message.sequence
312	            || envelope.topic != self.expected_topic
313	        {
314	            return Some(Err(ValidatedZmqSourceError::IdentityMismatch {
315	                expected_publisher_id: self.expected_publisher_id,
316	                expected_topic: self.expected_topic.clone(),
317	                frame_publisher_id: message.publisher_id,
318	                frame_sequence: message.sequence,
319	                envelope_publisher_id: envelope.publisher_id,
320	                envelope_sequence: envelope.sequence,
321	                envelope_topic: envelope.topic,
322	            }));
323	        }
324	
325	        Some(Ok(ValidatedEnvelope {
326	            publisher_id: envelope.publisher_id,
327	            sequence: envelope.sequence,
328	            published_at: envelope.published_at,
329	            payload: envelope.payload,
330	        }))
331	    }
332	}
