463	    fn start_socket_pump(
464	        mut socket: Subscribe,
465	        broadcast_tx: broadcast::Sender<Bytes>,
466	    ) -> tokio::task::JoinHandle<()> {
467	        tokio::spawn(async move {
468	            loop {
469	                let Some(result) = socket.next().await else {
470	                    tracing::info!("ZMQ socket stream ended");
471	                    break;
472	                };
473	
474	                let frames = match result {
475	                    Ok(frames) => frames,
476	                    Err(error) => {
477	                        tracing::error!(error = %error, "ZMQ receive error in socket pump");
478	                        break;
479	                    }
480	                };
481	
482	                match decode_multipart(frames, &[]) {
483	                    Ok(message) => {
484	                        tracing::trace!(
485	                            publisher_id = message.publisher_id,
486	                            sequence = message.sequence,
487	                            "Socket pump received ZMQ message"
488	                        );
489	                        let _ = broadcast_tx.send(message.payload);
490	                    }
491	                    Err(error) => {
492	                        tracing::warn!(error = %error, "Failed to decode ZMQ frame in socket pump");
493	                    }
494	                }
495	            }
496	
497	            tracing::info!("ZMQ socket pump task terminated");
498	        })
499	    }
500	}
