502	struct DecodedZmqMessage {
503	    publisher_id: u64,
504	    sequence: u64,
505	    payload: Bytes,
506	}
507	
508	fn decode_multipart(mut frames: Multipart, expected_topic: &[u8]) -> Result<DecodedZmqMessage> {
509	    if frames.len() != 4 {
510	        anyhow::bail!("unexpected ZMQ multipart frame count: {}", frames.len());
511	    }
512	
513	    if !expected_topic.is_empty() && &frames[0][..] != expected_topic {
514	        anyhow::bail!("ZMQ message topic disagrees with the exact subscription topic");
515	    }
516	
517	    let publisher_id_bytes = &frames[1];
518	    if publisher_id_bytes.len() != 8 {
519	        anyhow::bail!(
520	            "invalid ZMQ publisher ID frame length: {}",
521	            publisher_id_bytes.len()
522	        );
523	    }
524	    let publisher_id = u64::from_be_bytes(publisher_id_bytes[..].try_into().unwrap());
525	
526	    let sequence_bytes = &frames[2];
527	    if sequence_bytes.len() != 8 {
528	        anyhow::bail!(
529	            "invalid ZMQ sequence frame length: {}",
530	            sequence_bytes.len()
531	        );
532	    }
533	    let sequence = u64::from_be_bytes(sequence_bytes[..].try_into().unwrap());
534	
535	    let frame_message = frames
536	        .pop_back()
537	        .ok_or_else(|| anyhow!("ZMQ multipart message has no payload frame"))?;
538	    let frame_bytes = Bytes::from_owner(ZmqMessageOwner(frame_message));
539	    let frame = Frame::decode(frame_bytes)?;
540	
541	    Ok(DecodedZmqMessage {
542	        publisher_id,
543	        sequence,
544	        payload: frame.payload,
545	    })
546	}
