548	#[async_trait]
549	impl EventTransportRx for ZmqSubTransport {
550	    async fn subscribe(&self, _subject: &str) -> Result<WireStream> {
551	        let mut receiver = self.broadcast_tx.subscribe();
552	        let socket_pump_handle = Arc::clone(&self.socket_pump_handle);
553	
554	        let stream = stream! {
555	            // Keep the socket pump alive after the transport is dropped. The
556	            // final transport or subscription stream aborts the pump, which
557	            // drops its owned ZMQ socket instead of detaching the task.
558	            let _socket_pump_handle = socket_pump_handle;
559	            loop {
560	                match receiver.recv().await {
561	                    Ok(payload) => yield Ok(payload),
562	                    Err(tokio::sync::broadcast::error::RecvError::Lagged(skipped)) => {
563	                        tracing::warn!(skipped = skipped, "Subscriber lagged behind, skipped messages");
564	                    }
565	                    Err(tokio::sync::broadcast::error::RecvError::Closed) => {
566	                        tracing::info!("Broadcast channel closed");
567	                        break;
568	                    }
569	                }
570	            }
571	        };
572	
573	        Ok(Box::pin(stream))
574	    }
575	
576	    fn kind(&self) -> EventTransportKind {
577	        EventTransportKind::Zmq
578	    }
579	}
