82	    async fn compare_and_replace(
83	        &self,
84	        key: &Key,
85	        expected: bytes::Bytes,
86	        value: bytes::Bytes,
87	    ) -> Result<StoreOutcome, StoreError> {
88	        let k = make_key(&self.bucket_name, key);
89	        match self
90	            .client
91	            .kv_compare_and_put(k, expected, value, None)
92	            .await
93	            .map_err(|error| StoreError::EtcdError(error.to_string()))?
94	        {
95	            etcd::CompareAndPutOutcome::Updated => Ok(StoreOutcome::Created(0)),
96	            etcd::CompareAndPutOutcome::Missing => Err(StoreError::MissingKey(key.to_string())),
97	            etcd::CompareAndPutOutcome::Conflict => Err(StoreError::Retry),
98	        }
99	    }
