101	    async fn get(&self, key: &Key) -> Result<Option<bytes::Bytes>, StoreError> {
102	        let k = make_key(&self.bucket_name, key);
103	        tracing::trace!("etcd get: {k}");
104	
105	        let mut kvs = self
106	            .client
107	            .kv_get(k, None)
108	            .await
109	            .map_err(|e| StoreError::EtcdError(e.to_string()))?;
110	        if kvs.is_empty() {
111	            return Ok(None);
112	        }
113	        let (_, val) = kvs.swap_remove(0).into_key_value();
