118	        let k = make_key(&self.bucket_name, key);
119	        tracing::trace!("etcd delete: {k}");
120	        let _ = self
121	            .client
122	            .kv_delete(k, None)
123	            .await
124	            .map_err(|e| StoreError::EtcdError(e.to_string()))?;
