128	    async fn watch(
129	        &self,
130	    ) -> Result<Pin<Box<dyn futures::Stream<Item = WatchEvent> + Send + 'life0>>, StoreError> {
131	        let prefix = make_key(&self.bucket_name, &"".into());
132	        tracing::trace!("etcd watch: {prefix}");
133	        let watcher = self
134	            .client
135	            .kv_get_and_watch_prefix(&prefix)
136	            .await
137	            .map_err(|e| StoreError::EtcdError(e.to_string()))?;
138	        let (_, mut watch_stream) = watcher.dissolve();
139	        let output = stream! {
140	            while let Some(event) = watch_stream.recv().await {
141	                match event {
142	                    etcd::WatchEvent::Put(kv) => {
143	                        let (k, v) = kv.into_key_value();
144	                        let key = match String::from_utf8(k) {
145	                            Ok(k) => Key::new(k),
146	                            Err(err) => {
147	                                tracing::error!(%err, prefix, "Invalid UTF8 in etcd key");
148	                                continue;
149	                            }
150	                        };
151	                        let item = KeyValue::new(key, v.into());
152	                        yield WatchEvent::Put(item);
153	                    }
154	                    etcd::WatchEvent::Delete(kv) => {
155	                        let (k, _) = kv.into_key_value();
156	                        let key = match String::from_utf8(k) {
157	                            Ok(k) => Key::new(k),
158	                            Err(err) => {
159	                                tracing::error!(%err, prefix, "Invalid UTF8 in etcd key");
160	                                continue;
161	                            }
162	                        };
163	                        yield WatchEvent::Delete(key);
164	                    }
165	                    etcd::WatchEvent::Resync(kvs) => {
166	                        let mut snapshot = HashMap::with_capacity(kvs.len());
167	                        for kv in kvs {
168	                            let (k, v) = kv.into_key_value();
169	                            let key = match String::from_utf8(k) {
170	                                Ok(k) => Key::new(k),
171	                                Err(err) => {
172	                                    tracing::error!(%err, prefix, "Invalid UTF8 in etcd resync key");
173	                                    continue;
174	                                }
175	                            };
176	                            snapshot.insert(key, v.into());
177	                        }
178	                        yield WatchEvent::Resync(snapshot);
179	                    }
180	                }
181	            }
182	        };
183	        Ok(Box::pin(output))
184	    }
