191	            .client
192	            .kv_get_prefix(k)
193	            .await
194	            .map_err(|e| StoreError::EtcdError(e.to_string()))?;
195	        let out: HashMap<Key, bytes::Bytes> = resp
196	            .into_iter()
197	            .map(|kv| {
198	                let (k, v) = kv.into_key_value();
199	                (Key::new(String::from_utf8_lossy(&k).to_string()), v.into())
200	            })
201	            .collect();
