207	impl EtcdBucket {
208	    async fn create(
209	        &self,
210	        key: &Key,
211	        value: impl Into<Vec<u8>>,
212	    ) -> Result<StoreOutcome, StoreError> {
213	        let k = make_key(&self.bucket_name, key);
214	        tracing::trace!("etcd create: {k}");
215	
216	        match self
217	            .client
218	            .kv_create(k.as_str(), value.into(), None)
219	            .await
220	            .map_err(|e| StoreError::EtcdError(e.to_string()))?
221	        {
222	            None => {
223	                // Key was created successfully
224	                Ok(StoreOutcome::Created(1)) // version of new key is always 1
225	            }
226	            Some(revision) => Ok(StoreOutcome::Exists(revision)),
227	        }
228	    }
229	
230	    async fn update(
231	        &self,
232	        key: &Key,
233	        value: impl AsRef<[u8]>,
234	        revision: u64,
235	    ) -> Result<StoreOutcome, StoreError> {
236	        let version = revision;
237	        let k = make_key(&self.bucket_name, key);
238	        tracing::trace!("etcd update: {k}");
239	
240	        let kvs = self
241	            .client
242	            .kv_get(k.clone(), None)
243	            .await
244	            .map_err(|e| StoreError::EtcdError(e.to_string()))?;
245	        if kvs.is_empty() {
246	            return Err(StoreError::MissingKey(key.to_string()));
247	        }
248	        let current_version = kvs.first().unwrap().version() as u64;
249	        if current_version != version + 1 {
250	            tracing::warn!(
251	                current_version,
252	                attempted_next_version = version,
253	                %key,
254	                "update: Wrong revision"
255	            );
256	            // NATS does a resync_update, overwriting the key anyway and getting the new revision.
257	            // So we do too in etcd.
258	        }
259	
260	        let put_options = PutOptions::new()
261	            .with_lease(self.client.lease_id() as i64)
262	            .with_prev_key();
263	        let mut put_resp = self
264	            .client
265	            .kv_put_with_options(k, value, Some(put_options))
266	            .await
267	            .map_err(|e| StoreError::EtcdError(e.to_string()))?;
268	        Ok(match put_resp.take_prev_key() {
269	            // Should this be an error?
270	            // The key was deleted between our get and put. We re-created it.
271	            // Version of new key is always 1.
272	            // <https://etcd.io/docs/v3.5/learning/data_model/>
273	            None => StoreOutcome::Created(1),
274	            // Expected case, success
275	            Some(kv) if kv.version() as u64 == version + 1 => StoreOutcome::Created(version),
276	            // Should this be an error? Something updated the version between our get and put
277	            Some(kv) => StoreOutcome::Created(kv.version() as u64 + 1),
278	        })
279	    }
280	}
