358	    async fn test_concurrent_create(
359	        storage: &crate::storage::kv::Manager,
360	    ) -> Result<(), StoreError> {
361	        // Create a bucket for testing
362	        let bucket = Arc::new(tokio::sync::Mutex::new(
363	            storage
364	                .get_or_create_bucket("test_concurrent_bucket", None)
365	                .await?,
366	        ));
367	
368	        // Number of concurrent workers
369	        let num_workers = 10;
370	        let barrier = Arc::new(Barrier::new(num_workers));
371	
372	        // Shared test data
373	        let test_key: Key = Key::new(format!("concurrent_test_key_{}", uuid::Uuid::new_v4()));
374	        let test_value = "test_value";
375	
376	        // Spawn multiple tasks that will all try to create the same key simultaneously
377	        let mut handles = Vec::new();
378	        let success_count = Arc::new(tokio::sync::Mutex::new(0));
379	        let exists_count = Arc::new(tokio::sync::Mutex::new(0));
380	
381	        for worker_id in 0..num_workers {
382	            let bucket_clone = bucket.clone();
383	            let barrier_clone = barrier.clone();
384	            let key_clone = test_key.clone();
385	            let value_clone = format!("{}_from_worker_{}", test_value, worker_id);
386	            let success_count_clone = success_count.clone();
387	            let exists_count_clone = exists_count.clone();
388	
389	            let handle = tokio::spawn(async move {
390	                // Wait for all workers to be ready
391	                barrier_clone.wait().await;
392	
393	                // All workers try to create the same key at the same time
394	                let result = bucket_clone
395	                    .lock()
396	                    .await
397	                    .insert(&key_clone, value_clone.into(), 0)
398	                    .await;
399	
400	                match result {
401	                    Ok(StoreOutcome::Created(version)) => {
402	                        println!(
403	                            "Worker {} successfully created key with version {}",
404	                            worker_id, version
405	                        );
406	                        let mut count = success_count_clone.lock().await;
407	                        *count += 1;
408	                        Ok(version)
409	                    }
410	                    Ok(StoreOutcome::Exists(version)) => {
411	                        println!(
412	                            "Worker {} found key already exists with version {}",
413	                            worker_id, version
414	                        );
415	                        let mut count = exists_count_clone.lock().await;
416	                        *count += 1;
417	                        Ok(version)
418	                    }
419	                    Err(e) => {
420	                        println!("Worker {} got error: {:?}", worker_id, e);
421	                        Err(e)
422	                    }
423	                }
424	            });
425	
426	            handles.push(handle);
427	        }
428	
429	        // Wait for all workers to complete
430	        let mut results = Vec::new();
431	        for handle in handles {
432	            let result = handle.await.unwrap();
433	            if let Ok(version) = result {
434	                results.push(version);
435	            }
436	        }
437	
438	        // Verify results
439	        let final_success_count = *success_count.lock().await;
440	        let final_exists_count = *exists_count.lock().await;
441	
442	        println!(
443	            "Final counts - Created: {}, Exists: {}",
444	            final_success_count, final_exists_count
445	        );
446	
447	        // CRITICAL ASSERTIONS:
448	        // 1. Exactly ONE worker should have successfully created the key
449	        assert_eq!(
450	            final_success_count, 1,
451	            "Exactly one worker should create the key"
452	        );
453	
454	        // 2. All other workers should have gotten "Exists" response
455	        assert_eq!(
456	            final_exists_count,
457	            num_workers - 1,
458	            "All other workers should see key exists"
459	        );
460	
461	        // 3. Total successful operations should equal number of workers
462	        assert_eq!(
463	            results.len(),
464	            num_workers,
465	            "All workers should complete successfully"
466	        );
467	
468	        // 4. Verify the key actually exists in etcd
469	        let stored_value = bucket.lock().await.get(&test_key).await?;
470	        assert!(stored_value.is_some(), "Key should exist in etcd");
471	
472	        // 5. The stored value should be from one of the workers
473	        let stored_str = String::from_utf8(stored_value.unwrap().to_vec()).unwrap();
474	        assert!(
475	            stored_str.starts_with(test_value),
476	            "Stored value should match expected prefix"
477	        );
478	
479	        // Clean up
480	        bucket.lock().await.delete(&test_key).await?;
481	
482	        Ok(())
